package dev.pocketengine.features.local.project;
import static org.junit.Assert.*;import dev.pocketengine.core.RunControl;import java.io.*;import java.util.concurrent.atomic.AtomicBoolean;import org.json.*;import org.junit.*;
public final class ProjectDocumentImportTest {
 private static final byte[] RAW={0,(byte)255,3};private static final String ID="11111111-1111-1111-1111-111111111111",PROJECT="22222222-2222-2222-2222-222222222222";
 private static final class Doc implements ProjectDocumentImport.Document{ProjectDocumentImport.Metadata meta;byte[] bytes=RAW;boolean opened,closed;Doc(ProjectDocumentImport.Metadata meta){this.meta=meta;}public ProjectDocumentImport.Metadata metadata(){return meta;}public InputStream open(){opened=true;return new ByteArrayInputStream(bytes);}public void close(){closed=true;}}
 private Doc doc(Long size){return new Doc(new ProjectDocumentImport.Metadata("asset.bin","application/octet-stream",size,false,false,false));}
 @Test public void actualSelectedBytesStayPrivateAndOnlyBoundedMetadataAndHexReachTheReview()throws Exception{RunControl control=new RunControl();Doc doc=doc(3L);try(var source=ProjectDocumentImport.read(doc,control)){JSONObject view=source.view();assertTrue(doc.opened);assertTrue(doc.closed);assertEquals(3,source.size());assertEquals(ProjectSources.sha256(RAW),view.getString("sha256"));assertEquals("00ff03",view.getString("previewHex"));assertFalse(view.getBoolean("sourceUriIncluded"));assertFalse(view.getBoolean("bodyIncluded"));assertFalse(view.getBoolean("providerAtomicSnapshot"));assertEquals("asset.bin",source.suggestedPath());assertFalse(view.has("contentBase64"));}}
 @Test public void invalidVirtualPartialDirectoryAndDeclaredOversizeAreRejectedBeforeOpeningProviderBytes()throws Exception{for(ProjectDocumentImport.Metadata meta:new ProjectDocumentImport.Metadata[]{new ProjectDocumentImport.Metadata(".env","x",3L,false,false,false),new ProjectDocumentImport.Metadata("v","x",3L,false,true,false),new ProjectDocumentImport.Metadata("partial","x",3L,false,false,true),new ProjectDocumentImport.Metadata("dir","x",3L,true,false,false),new ProjectDocumentImport.Metadata("huge","x",(long)ProjectSources.MAX_FILE_BYTES+1,false,false,false),new ProjectDocumentImport.Metadata("bad","x",-1L,false,false,false)}){Doc doc=new Doc(meta);assertThrows(IllegalArgumentException.class,()->ProjectDocumentImport.read(doc,new RunControl()));assertFalse(doc.opened);assertTrue(doc.closed);}}
 @Test public void boundedStreamAndExactDeclaredSizeNeverReturnATruncatedSource()throws Exception{Doc mismatch=doc(4L);assertThrows(SecurityException.class,()->ProjectDocumentImport.read(mismatch,new RunControl()));Doc huge=doc(null);huge.bytes=new byte[ProjectSources.MAX_FILE_BYTES+1];assertThrows(IllegalArgumentException.class,()->ProjectDocumentImport.read(huge,new RunControl()));assertTrue(huge.closed);Doc unknown=doc(null);try(var source=ProjectDocumentImport.read(unknown,new RunControl())){assertEquals(3,source.size());assertTrue(source.view().isNull("declaredBytes"));}}
 @Test public void sourceReleaseAndCancellationCannotProduceAFreshReviewOrRetry()throws Exception{RunControl control=new RunControl();var source=ProjectDocumentImport.read(doc(3L),control);source.close();assertThrows(IllegalStateException.class,source::view);assertThrows(IllegalStateException.class,()->ProjectDocumentImport.reviewForHost(new Object(),source,control,ID,PROJECT,"a".repeat(64),"asset.bin","absent"));RunControl cancelled=new RunControl();cancelled.cancel();Doc notOpened=doc(3L);assertThrows(Exception.class,()->ProjectDocumentImport.read(notOpened,cancelled));assertFalse(notOpened.opened);}
 @Test public void oneOpaqueReviewBindsActualIssuerControlTargetAndSeenDigestBeforeGivingBytes()throws Exception{Object issuer=new Object();RunControl control=new RunControl();try(var source=ProjectDocumentImport.read(doc(3L),control)){var review=ProjectDocumentImport.reviewForHost(issuer,source,control,ID,PROJECT,"a".repeat(64),"asset.bin","absent");JSONObject view=review.view();assertEquals("asset.bin",view.getString("path"));assertThrows(SecurityException.class,()->review.claim(new Object(),control,view.getString("reviewDigest")));assertThrows(SecurityException.class,()->review.claim(issuer,new RunControl(),view.getString("reviewDigest")));assertThrows(SecurityException.class,()->review.claim(issuer,control,"0".repeat(64)));assertArrayEquals(RAW,review.claim(issuer,control,view.getString("reviewDigest")));assertThrows(SecurityException.class,()->review.claim(issuer,control,view.getString("reviewDigest")));}}
 @Test public void modelRunUnsafePathsAndDependencyTargetsCannotMintAnOwnerImportSelection()throws Exception{RunControl task=new RunControl();task.bindHostRun(ID,PROJECT,1);Doc doc=doc(3L);assertThrows(SecurityException.class,()->ProjectDocumentImport.read(doc,task));assertFalse(doc.opened);RunControl original=new RunControl();try(var source=ProjectDocumentImport.read(doc(3L),original)){for(String path:new String[]{"../escape","/tmp/file","node_modules/a",".git/config","a//b"})assertThrows(Exception.class,()->ProjectDocumentImport.reviewForHost(new Object(),source,original,ID,PROJECT,"a".repeat(64),path,"absent"));assertThrows(SecurityException.class,()->ProjectDocumentImport.reviewForHost(new Object(),source,task,ID,PROJECT,"a".repeat(64),"asset.bin","absent"));}}
 @Test public void previewDoesNotPretendToBeCompleteAndFileNamesAreHintsNotHostPaths()throws Exception{Doc doc=new Doc(new ProjectDocumentImport.Metadata("../../not-a-target","x",null,false,false,false));doc.bytes=new byte[100];try(var source=ProjectDocumentImport.read(doc,new RunControl())){assertEquals("imported-file.bin",source.suggestedPath());assertEquals(64,source.view().getInt("previewBytes"));assertTrue(source.view().getBoolean("previewTruncated"));assertEquals(128,source.view().getString("previewHex").length());}}
}
